def check_m2(a1):
    # a2 = 335(a1 - 1) / (328*a1 - 335)
    numerator = 335 * (a1 - 1)
    denominator = 328 * a1 - 335

    if denominator == 0:
        return None # Division by zero

    # Check if a2 is a positive integer
    if numerator % denominator == 0:
        a2 = numerator // denominator
        # Check constraints: a2 > 1, a1 > 1, a2 != a1
        if a2 > 1 and a1 > 1 and a2 != a1:
            return (a1, a2)
    return None

solutions = []
# Search up to a reasonable limit based on the theoretical analysis (a1 <= 1.044 for division to be possible if k>=1)
# We search up to 10 just to be absolutely certain that our analysis covers no edge cases.
for a1 in range(2, 11):
    result = check_m2(a1)
    if result:
        solutions.append(result)

print(f"Found solutions for m=2: {solutions}")

